page(s,[('Четыре утренних действия',['Пробуждение и вставание с постели не совпадают. После них в тексте могут быть мытьё и завтрак; порядок определяется самим текстом.'],[W['se-reveiller']['example'],W['se-lever']['example'],W['se-laver']['example'],W['prendre-petit-dejeuner']['example']]),('Выбранные формы о себе',['В трёх показанных возвратных образцах после я используется одна и та же короткая часть. Здесь изучаются эти формы, без полной таблицы лиц.'],[ex('Je me lève. Je me lave.','Я встаю с постели. Я моюсь.','жё мё лэ́в. жё мё ла́в')]),('Входная опора',['Основные части суток и знакомые короткие реплики повторяются. Межуровневой зависимости нет: можно опираться на эквивалентные базовые знания.'],[ex('Le matin, je bois de l’eau.','Утром я пью воду.','лё матэ(н), жё буа дё ло́')])])

